import requests, xml.etree.ElementTree as ET
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':'25076128','rettype':'abstract','retmode':'xml'},timeout=20)
root=ET.fromstring(r.text)
for el in root.findall('.//ArticleTitle'): print('TITLE:', ''.join(el.itertext()))
for el in root.findall('.//Abstract/AbstractText'): print('ABSTRACT:',el.attrib, ''.join(el.itertext()))
for el in root.findall('.//Author'): print('AUTHOR:', ' '.join((a.text or '') for a in el.findall('LastName')+el.findall('Initials')))
print('JOURNAL:', ''.join(root.find('.//Journal/Title').itertext()) if root.find('.//Journal/Title') is not None else '')
print('DOI:', [x.text for x in root.findall('.//ArticleId') if x.attrib.get('IdType')=='doi'])
